<script lang="ts">import{Check,Square,Trash2}from'@lucide/svelte';import type{DischargeEvent}from'$lib/services/bms-api';let{items,onselect,onstop,onremove,onactivate}:{items:DischargeEvent[];onselect:(e:DischargeEvent)=>void;onstop:(e:DischargeEvent)=>void;onremove:(e:DischargeEvent)=>void;onactivate:(e:DischargeEvent)=>void}=$props();</script>
<div class="table"><table><thead><tr><th>Event</th><th>Status</th><th>Type</th><th>Start</th><th>Used Ah</th><th>SoH</th><th>Mode</th><th></th></tr></thead><tbody>{#if items.length}{#each items as e}<tr onclick={()=>onselect(e)}><td>{e.id}</td><td><span class="badge">{e.status}</span></td><td>{e.eventType}</td><td>{new Date(e.startTime).toLocaleString()}</td><td>{e.usedAh??'—'}</td><td>{e.computedSoh===null?'—':`${e.computedSoh.toFixed(1)}%`}</td><td>{e.automaticMode?'Automatic':'Manual'}</td><td class="actions">{#if e.status==='PENDING'||e.status==='RUNNING'}<button title="Stop" onclick={(x)=>{x.stopPropagation();onstop(e)}}><Square size={15}/></button>{/if}{#if e.status==='SUCCESS'&&!e.activeBaseline}<button title="Activate baseline" onclick={(x)=>{x.stopPropagation();onactivate(e)}}><Check size={15}/></button>{/if}{#if e.status!=='PENDING'&&e.status!=='RUNNING'}<button class="danger" title="Delete" onclick={(x)=>{x.stopPropagation();onremove(e)}}><Trash2 size={15}/></button>{/if}</td></tr>{/each}{:else}<tr><td colspan="8" class="empty">No discharge event for this string.</td></tr>{/if}</tbody></table></div>
<style>.table{overflow-x:auto}.table table{width:100%;min-width:800px;border-collapse:collapse}th,td{padding:12px 14px;border-bottom:1px solid #edf1f6;color:#56657c;font-size:13px;text-align:left}th{color:#7b879a;background:#f8faff;font-size:11px;font-weight:500;text-transform:uppercase}.empty{height:130px;text-align:center}.badge{padding:4px 7px;border-radius:11px;color:#31569f;background:#edf3ff;font-size:11px}.actions{display:flex;justify-content:flex-end;gap:5px}.actions button{display:grid;width:30px;height:30px;place-items:center;border:1px solid #dce6fb;border-radius:7px;color:#31569f;background:#f6f9ff;cursor:pointer}.actions .danger{color:#c83229;background:#fff6f5;border-color:#f3d8d5}</style>
